// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testFuzz_property(
        uint64 number,
        uint64 timestamp,
        uint256 basefee,
        bytes32 hash,
        uint64 sequenceNumber,
        bytes32 batcherHash,
        uint256 l1FeeOverhead,
        uint256 l1FeeScalar
    ) public {
        vm.assume(batcherHash != bytes32(0));
        // depositorAccount defaults to address(0); only that address can call
        vm.prank(address(0));
        c.setL1BlockValues(number, timestamp, basefee, hash, sequenceNumber, batcherHash, l1FeeOverhead, l1FeeScalar);
        // Reference never writes state: batcherHash stays zero for every input.
        assertTrue(c.batcherHash() == bytes32(0));
    }
}
